+function hiddenState(revision: string): ComposerSuggestionsState {
+	return {
+		status: "hidden",
+		hiddenReason: "user",
+		title: TITLE,
+		command: COMMAND,
+		revision,
+		items: [],
+		canRefresh: false,
+	};
+}
